WITH valid AS (SELECT id, channel, promo_code, starts_on, discount_pct, MONTH(starts_on) AS starts_on_month FROM promotions WHERE starts_on > TO_DATE('2024-01-26') AND channel IS NOT NULL), enriched AS (SELECT *, SUM(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct, LAG(starts_on_month, 1) OVER (ORDER BY starts_on, id) AS prev_starts_on_month, RANK() OVER w_recent AS discount_pct_rank FROM valid WINDOW w_recent AS (PARTITION BY promo_code ORDER BY discount_pct DESC)), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY starts_on, id) AS rn FROM enriched) ranked WHERE rn = 1), summary AS (SELECT CASE WHEN discount_pct_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_rank_tier, CASE WHEN discount_pct >= 0.34 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, SIZE(COLLECT_SET(channel)) AS num_channels, AVG(prev_starts_on_month) FILTER (WHERE channel = 'web') AS web_avg_prev_starts_on_month, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(promo_code)) AS promo_code_list, SIZE(COLLECT_SET(channel)) AS num_channels_2, RANK() OVER (PARTITION BY CASE WHEN discount_pct_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END ORDER BY SIZE(COLLECT_SET(channel)) DESC) AS num_channels_rank FROM deduped GROUP BY CASE WHEN discount_pct_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN discount_pct >= 0.34 THEN 'PREMIUM' ELSE 'STANDARD' END) SELECT discount_pct_rank_tier, discount_pct_tier, num_channels, store_count, cnt, promo_code_list, num_channels_2 FROM summary;
